sys_script_email.script:
(function runMailScript( /* GlideRecord */ current, /* TemplatePrinter */ template,
    /* Optional EmailOutbound */
    email, /* Optional GlideRecord */ email_action,
    /* Optional GlideRecord */
    event) {



    attachURL();

    function attachURL() {
        // attach URL from related New risk 
        var attachLink = "<a href='https://" + gs.getProperty("instance_name") +
            ".service-now.com/zone?id=ticket&is_new_order=true&table=x_gamlp_irm_risk_c_risk&sys_id=" +
            current.sys_id + "'>Ouvrir la demande d'ajout d'un risque</a>";

        template.print(attachLink + "<br />");
    }
})(current, template, email, email_action, event);
